create or replace function public.update_lead_status(p_lead_id uuid,p_status public.lead_status,p_note text default null) returns void language plpgsql security definer set search_path=public as $$declare v_from public.lead_status;begin if not public.is_staff() then raise exception 'forbidden';end if;select status into v_from from leads where id=p_lead_id for update;if v_from is null then raise exception 'lead_not_found';end if;update leads set status=p_status,updated_at=now() where id=p_lead_id;if v_from is distinct from p_status or nullif(trim(coalesce(p_note,'')),'') is not null then insert into lead_activities(lead_id,activity_type,from_status,to_status,note,created_by) values(p_lead_id,case when v_from is distinct from p_status then 'status_changed' else 'note' end,v_from,p_status,nullif(trim(coalesce(p_note,'')),''),auth.uid());end if;end$$;revoke all on function public.update_lead_status(uuid,public.lead_status,text) from public;grant execute on function public.update_lead_status(uuid,public.lead_status,text) to authenticated;